import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

const waitFor = async (predicate, {timeout = 500, interval = 1} = {}) => {
	const start = Date.now();

	while (!predicate()) {
		if (Date.now() - start > timeout) {
			throw new Error('Timed out waiting for predicate');
		}

		await delay(interval);
	}
};

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	let resolved = false;
	const idle = limit.onIdle().then(() => {
		resolved = true;
	});

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await idle;
	t.true(resolved);
});

test('onIdle waits for running and queued tasks', async t => {
	const limit = pLimit(1);
	const order = [];

	const idle = limit.onIdle().then(() => {
		order.push('idle');
	});

	limit(async () => {
		await delay(20);
		order.push('first');
	});
	limit(async () => {
		await delay(5);
		order.push('second');
	});

	await idle;

	t.deepEqual(order, ['first', 'second', 'idle']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle supports multiple waiters', async t => {
	const limit = pLimit(2);

	const first = limit(() => delay(30));
	const second = limit(() => delay(10));

	const resolutions = [];
	const idleOne = limit.onIdle().then(() => resolutions.push('one'));
	const idleTwo = limit.onIdle().then(() => resolutions.push('two'));

	await Promise.all([first, second, idleOne, idleTwo]);

	t.deepEqual(resolutions.sort(), ['one', 'two']);
});

test('onIdle resolves after a rejected task', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const rejected = limit(async () => {
		await delay(10);
		throw error;
	});
	const following = limit(async () => {
		await delay(10);
		return 'ok';
	});

	const idle = limit.onIdle();

	await t.throwsAsync(rejected, {is: error});
	t.is(await following, 'ok');
	await idle;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle accounts for reserved slots that have not started running', async t => {
	const limit = pLimit(2);
	const started = [];

	limit(() => {
		started.push(1);
		return delay(20);
	});
	limit(() => {
		started.push(2);
		return delay(20);
	});

	// Both slots are reserved synchronously, before the functions have started.
	t.is(limit.activeCount, 2);
	t.is(started.length, 0);

	let resolved = false;
	const idle = limit.onIdle().then(() => {
		resolved = true;
	});

	t.false(resolved);
	await idle;
	t.true(resolved);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not resolve early when a task enqueues another task', async t => {
	const limit = pLimit(1);
	const events = [];

	const idle = limit.onIdle().then(() => {
		events.push('idle');
	});

	limit(async () => {
		await delay(10);
		limit(async () => {
			await delay(10);
			events.push('inner');
		});
		events.push('outer');
	});

	await idle;

	t.deepEqual(events, ['outer', 'inner', 'idle']);
});

test('onIdle does not resolve early when enqueue happens after task resolution', async t => {
	const limit = pLimit(1);
	const events = [];

	let resolveFirst;
	const first = limit(() => new Promise(resolve => {
		resolveFirst = resolve;
	}));

	const idle = limit.onIdle().then(() => {
		events.push('idle');
	});

	await Promise.resolve();
	resolveFirst();

	// Enqueue from the continuation of the resolved task, before idle is observed.
	first.then(() => {
		limit(async () => {
			await delay(10);
			events.push('inner');
		});
	});

	await idle;

	t.true(events.includes('inner'));
	t.deepEqual(events, ['inner', 'idle']);
});

test('clearQueue releases onIdle waiters when no tasks are active', async t => {
	const limit = pLimit(1);

	const running = limit(() => delay(20));
	// These discarded promises stay unresolved because `rejectOnClear` is false.
	limit(() => delay(1000));
	limit(() => delay(1000));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	const idle = limit.onIdle();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	// Idle should not be reported while the running task is still active.
	let resolved = false;
	idle.then(() => {
		resolved = true;
	});

	await delay(5);
	t.false(resolved);

	await running;
	await idle;
	t.true(resolved);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue releases onIdle waiters when the queue is already empty and idle', async t => {
	const limit = pLimit(1);

	const pending = limit(() => delay(1000));
	await Promise.resolve();
	limit.clearQueue();

	// The discarded promise is unresolved, but the queue is empty and nothing is active.
	const idle = limit.onIdle();
	let resolved = false;
	idle.then(() => {
		resolved = true;
	});

	await idle;
	t.true(resolved);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	// Avoid an unhandled rejection warning if the discarded promise ever settles.
	pending.catch(() => {});
});

test('clearQueue with rejectOnClear releases onIdle waiters', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});

	const running = limit(() => delay(20));
	const pending = limit(() => delay(1000));

	await Promise.resolve();
	const idle = limit.onIdle();

	limit.clearQueue();
	pending.catch(() => {});

	await running;
	await idle;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle is exposed on limitFunction', async t => {
	const limitedFunction = limitFunction(async () => {
		await delay(20);
		return 'ok';
	}, {concurrency: 1});

	t.is(typeof limitedFunction.onIdle, 'function');

	const first = limitedFunction();
	const second = limitedFunction();

	let resolved = false;
	const idle = limitedFunction.onIdle().then(() => {
		resolved = true;
	});

	t.false(resolved);
	await Promise.all([first, second]);
	await idle;
	t.true(resolved);
});

test('onIdle preserves FIFO order', async t => {
	const limit = pLimit(1);
	const order = [];

	const promises = [1, 2, 3, 4].map(value => limit(async () => {
		await delay(5);
		order.push(value);
		return value;
	}));

	const idle = limit.onIdle();
	await Promise.all([...promises, idle]);

	t.deepEqual(order, [1, 2, 3, 4]);
});

test('onIdle works across concurrency changes', async t => {
	const limit = pLimit(1);
	const order = [];

	limit(async () => {
		await delay(10);
		order.push(1);
	});
	limit(async () => {
		await delay(10);
		order.push(2);
	});
	limit(async () => {
		await delay(10);
		order.push(3);
	});

	const idle = limit.onIdle();

	limit.concurrency = 2;

	await idle;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	t.deepEqual(order, [1, 2, 3]);
});

test('onIdle called repeatedly across idle cycles', async t => {
	const limit = pLimit(1);

	await limit.onIdle();

	await limit(async () => delay(10));
	await limit.onIdle();

	await Promise.all([
		limit(async () => delay(10)),
		limit(async () => delay(10)),
	]);

	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

// Keep a helper referenced so linting does not flag it as unused if a test is skipped.
void waitFor;

