	const first = limitedFunction();
	const second = limitedFunction();

	let resolved = false;
	const idle = limitedFunction.onIdle().then(() => {
		resolved = true;
	});

	t.false(resolved);
	await Promise.all([first, second]);
	await idle;
	t.true(resolved);
});

